const raw = String($json.message?.content ?? '').trim();
const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
let plan;
try { plan = JSON.parse(cleaned); } catch (error) { throw new Error('Router did not return valid JSON: ' + raw); }
if (!['coder', 'researcher', 'general'].includes(plan.target_worker)) throw new Error('Router returned an unsupported target_worker.');
const task = $('Prepare Router Input').first().json.task;
const stepElapsedMs = Math.max(0, Date.now() - Number($('Prepare Router Input').first().json.stepStartedAt || Date.now()));
const usage = { stepElapsedMs, model: 'qwen3.5:2b', promptTokens: Number($json.prompt_eval_count || 0), generatedTokens: Number($json.eval_count || 0), timingsMs: { total: Number.isFinite(Number($json.total_duration)) ? Number($json.total_duration) / 1e6 : null, load: Number.isFinite(Number($json.load_duration)) ? Number($json.load_duration) / 1e6 : null, promptEval: Number.isFinite(Number($json.prompt_eval_duration)) ? Number($json.prompt_eval_duration) / 1e6 : null, generation: Number.isFinite(Number($json.eval_duration)) ? Number($json.eval_duration) / 1e6 : null } };
const logLine = JSON.stringify({ executionId: $execution.id, timestamp: new Date().toISOString(), step: 'Router', model: usage.model, input: { task }, output: raw, usage, timingsMs: usage.timingsMs, stepElapsedMs }) + '\n';
return [{ json: { task, plan, retryCount: 0, retryFeedback: '', tokenUsage: [usage], logLine } }];

const state = $('Prepare Coder Input').item.json;
const stepElapsedMs = Math.max(0, Date.now() - Number(state.stepStartedAt || Date.now()));
const model = 'qwen2.5-coder:7b-instruct';
const workerOutput = String($json.message?.content ?? '');
const usage = { stepElapsedMs, model, promptTokens: Number($json.prompt_eval_count || 0), generatedTokens: Number($json.eval_count || 0), timingsMs: { total: Number.isFinite(Number($json.total_duration)) ? Number($json.total_duration) / 1e6 : null, load: Number.isFinite(Number($json.load_duration)) ? Number($json.load_duration) / 1e6 : null, promptEval: Number.isFinite(Number($json.prompt_eval_duration)) ? Number($json.prompt_eval_duration) / 1e6 : null, generation: Number.isFinite(Number($json.eval_duration)) ? Number($json.eval_duration) / 1e6 : null } };
const logLine = JSON.stringify({ executionId: $execution.id, timestamp: new Date().toISOString(), step: 'Coding Specialist', model, input: { task: state.task, successCriteria: state.plan.success_criteria || 'Not specified', files: state.plan.files || [], retryFeedback: state.retryFeedback || 'None' }, output: workerOutput, usage, timingsMs: usage.timingsMs, stepElapsedMs }) + '\n';
const tokenUsage = [...(state.tokenUsage || []), usage];
return [{ json: { ...state, tokenUsage, worker: 'coder', workerOutput, logLine } }];

const state = $('Prepare General Input').item.json;
const stepElapsedMs = Math.max(0, Date.now() - Number(state.stepStartedAt || Date.now()));
const model = 'qwen3.5:4b';
const workerOutput = String($json.message?.content ?? '');
const usage = { stepElapsedMs, model, promptTokens: Number($json.prompt_eval_count || 0), generatedTokens: Number($json.eval_count || 0), timingsMs: { total: Number.isFinite(Number($json.total_duration)) ? Number($json.total_duration) / 1e6 : null, load: Number.isFinite(Number($json.load_duration)) ? Number($json.load_duration) / 1e6 : null, promptEval: Number.isFinite(Number($json.prompt_eval_duration)) ? Number($json.prompt_eval_duration) / 1e6 : null, generation: Number.isFinite(Number($json.eval_duration)) ? Number($json.eval_duration) / 1e6 : null } };
const logLine = JSON.stringify({ executionId: $execution.id, timestamp: new Date().toISOString(), step: 'General Worker', model, input: { task: state.task, successCriteria: state.plan.success_criteria || 'Not specified', retryFeedback: state.retryFeedback || 'None' }, output: workerOutput, usage, timingsMs: usage.timingsMs, stepElapsedMs }) + '\n';
const tokenUsage = [...(state.tokenUsage || []), usage];
return [{ json: { ...state, tokenUsage, worker: state.plan.target_worker, workerOutput, logLine } }];

const raw = String($json.message?.content ?? '').trim();
const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
let review;
try { review = JSON.parse(cleaned); } catch (error) { throw new Error('Verifier did not return valid JSON: ' + raw); }
if (typeof review.passed !== 'boolean') throw new Error('Verifier response must contain a boolean passed field.');
const state = $('Prepare Verification Input').item.json;
const stepElapsedMs = Math.max(0, Date.now() - Number(state.stepStartedAt || Date.now()));
const model = 'qwen3.5:4b';
const feedback = String(review.feedback ?? '');
const usage = { stepElapsedMs, model, promptTokens: Number($json.prompt_eval_count || 0), generatedTokens: Number($json.eval_count || 0), timingsMs: { total: Number.isFinite(Number($json.total_duration)) ? Number($json.total_duration) / 1e6 : null, load: Number.isFinite(Number($json.load_duration)) ? Number($json.load_duration) / 1e6 : null, promptEval: Number.isFinite(Number($json.prompt_eval_duration)) ? Number($json.prompt_eval_duration) / 1e6 : null, generation: Number.isFinite(Number($json.eval_duration)) ? Number($json.eval_duration) / 1e6 : null } };
const logLine = JSON.stringify({ executionId: $execution.id, timestamp: new Date().toISOString(), step: 'Verifier', model, input: { task: state.task, successCriteria: state.plan.success_criteria || 'Not specified', worker: state.worker, workerOutput: state.workerOutput }, output: { passed: review.passed, feedback }, usage, timingsMs: usage.timingsMs, stepElapsedMs }) + '\n';
const tokenUsage = [...(state.tokenUsage || []), usage];
return [{ json: { ...state, tokenUsage, passed: review.passed, feedback, logLine } }];

const state = $('Prepare Debugger Input').item.json;
const stepElapsedMs = Math.max(0, Date.now() - Number(state.stepStartedAt || Date.now()));
const model = 'deepseek-r1:7b';
const debuggerAnalysis = String($json.message?.content ?? '');
const usage = { stepElapsedMs, model, promptTokens: Number($json.prompt_eval_count || 0), generatedTokens: Number($json.eval_count || 0), timingsMs: { total: Number.isFinite(Number($json.total_duration)) ? Number($json.total_duration) / 1e6 : null, load: Number.isFinite(Number($json.load_duration)) ? Number($json.load_duration) / 1e6 : null, promptEval: Number.isFinite(Number($json.prompt_eval_duration)) ? Number($json.prompt_eval_duration) / 1e6 : null, generation: Number.isFinite(Number($json.eval_duration)) ? Number($json.eval_duration) / 1e6 : null } };
const logLine = JSON.stringify({ executionId: $execution.id, timestamp: new Date().toISOString(), step: 'Deep Debugger', model, input: { task: state.task, workerOutput: state.workerOutput, verifierFeedback: state.feedback }, output: debuggerAnalysis, usage, timingsMs: usage.timingsMs, stepElapsedMs }) + '\n';
const tokenUsage = [...(state.tokenUsage || []), usage];
return [{ json: { ...state, tokenUsage, debuggerAnalysis, logLine } }];

const state = $input.first().json;
const retryCount = Number(state.retryCount || 0) + 1;
const notes = [state.feedback, state.debuggerAnalysis].filter(Boolean).join('\n');
return [{ json: { ...state, retryCount, retryFeedback: notes, passed: false } }];

const d = $input.first().json;
const usageByModel = {};
for (const call of d.tokenUsage || []) {
  const model = call.model || 'unknown';
  if (!usageByModel[model]) usageByModel[model] = { promptTokens: 0, generatedTokens: 0, totalTokens: 0, calls: 0, totalDurationMs: 0, totalStepElapsedMs: 0 };
  const promptTokens = Number(call.promptTokens || 0);
  const generatedTokens = Number(call.generatedTokens || 0);
  usageByModel[model].promptTokens += promptTokens;
  usageByModel[model].generatedTokens += generatedTokens;
  usageByModel[model].totalTokens += promptTokens + generatedTokens;
  usageByModel[model].calls += 1;
  usageByModel[model].totalDurationMs += Number(call.timingsMs?.total || 0);
  usageByModel[model].totalStepElapsedMs += Number(call.stepElapsedMs || 0);
}
const tokenTotals = Object.values(usageByModel).reduce((totals, model) => ({ promptTokens: totals.promptTokens + model.promptTokens, generatedTokens: totals.generatedTokens + model.generatedTokens, totalTokens: totals.totalTokens + model.totalTokens, modelCalls: totals.modelCalls + model.calls }), { promptTokens: 0, generatedTokens: 0, totalTokens: 0, modelCalls: 0 });
return [{ json: { task: d.task, worker: d.worker || d.plan?.target_worker || 'unknown', passed: d.passed === true, result: d.workerOutput || '', feedback: d.feedback || (d.retryCount > 2 ? 'Maximum of two retries reached.' : ''), debuggerAnalysis: d.debuggerAnalysis || '', retriesUsed: Math.min(Number(d.retryCount || 0), 2), tokenUsageByModel: usageByModel, tokenTotals, interactionLogFile: '.n8n/workflow-interactions.jsonl' } }];

const d = $input.first().json;
const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const formatPlainText = (value) => escapeHtml(value)
  .replace(/^### (.+)$/gm, '<h3>$1</h3>')
  .replace(/^## (.+)$/gm, '<h2>$1</h2>')
  .replace(/^# (.+)$/gm, '<h1>$1</h1>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/`([^`]+)`/g, '<code>$1</code>')
  .replace(/\n/g, '<br>');
const formatMarkdown = (value) => {
  const markdown = String(value ?? '');
  const codeBlock = /```([a-zA-Z0-9_+.-]*)\n?([\s\S]*?)```/g;
  let html = '';
  let cursor = 0;
  let match;
  while ((match = codeBlock.exec(markdown)) !== null) {
    html += formatPlainText(markdown.slice(cursor, match.index));
    const language = match[1] ? `<small>${escapeHtml(match[1])}</small>` : '';
    html += `${language}<pre><code>${escapeHtml(match[2].replace(/\n$/, ''))}</code></pre>`;
    cursor = codeBlock.lastIndex;
  }
  html += formatPlainText(markdown.slice(cursor));
  return html || '<em>No response content was returned.</em>';
};
const status = d.passed ? 'Completed successfully' : 'Completed with items to review';
const usage = d.tokenUsageByModel || {};
const rows = Object.entries(usage).map(([model, stats]) => `<tr><td>${escapeHtml(model)}</td><td>${Number(stats.calls || 0)}</td><td>${Number(stats.promptTokens || 0).toLocaleString()}</td><td>${Number(stats.generatedTokens || 0).toLocaleString()}</td><td>${(Number(stats.totalDurationMs || 0) / 1000).toFixed(1)} s</td><td>${(Number(stats.totalStepElapsedMs || 0) / 1000).toFixed(1)} s</td></tr>`).join('');
const feedback = d.feedback ? `<section><h2>Verifier feedback</h2><p>${formatMarkdown(d.feedback)}</p></section>` : '';
const debuggerSection = d.debuggerAnalysis ? `<section><h2>Debug notes</h2><div>${formatMarkdown(d.debuggerAnalysis)}</div></section>` : '';
const html = `<main><h1>${escapeHtml(status)}</h1><p><strong>Task:</strong> ${escapeHtml(d.task)}</p><p><strong>Worker:</strong> ${escapeHtml(d.worker)} &nbsp; <strong>Retries:</strong> ${Number(d.retriesUsed || 0)}</p><section><h2>Result</h2><div>${formatMarkdown(d.result)}</div></section>${feedback}${debuggerSection}<section><h2>Usage and timing</h2><p>${Number(d.tokenTotals?.modelCalls || 0)} model calls · ${Number(d.tokenTotals?.totalTokens || 0).toLocaleString()} tokens (including ${Number(d.tokenTotals?.promptTokens || 0).toLocaleString()} prompt and ${Number(d.tokenTotals?.generatedTokens || 0).toLocaleString()} generated)</p><table><thead><tr><th>Model</th><th>Calls</th><th>Prompt tokens</th><th>Generated tokens</th><th>Ollama time</th><th>Step elapsed</th></tr></thead><tbody>${rows || '<tr><td colspan="6">No model usage data</td></tr>'}</tbody></table></section><p><small>Interaction details are saved to ${escapeHtml(d.interactionLogFile || '.n8n/workflow-interactions.jsonl')}.</small></p></main>`;
return [{ json: { ...d, formattedResultHtml: html } }];
